cypress_script:
describe('Tool Shop Product Catalogue', () => {
  it('should search for a product using the search bar', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('#search-query').type('hammer');
    cy.get('[data-test="search-submit"]').click();
    cy.url().should('include', 'search=hammer');
  });

  it('should not change the URL when submitting an empty search', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('[data-test="search-submit"]').click();
    cy.url().should('eq', 'https://practicesoftwaretesting.com/');
    cy.get('#search-query').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Tool Shop Product Catalogue', () => {
  test('should search for a product using the search bar', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.fill('#search-query', 'hammer');
    await page.click('[data-test="search-submit"]');
    await expect(page).toHaveURL(/search=hammer/);
  });

  test('should not change the URL when submitting an empty search', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.click('[data-test="search-submit"]');
    await expect(page).toHaveURL('https://practicesoftwaretesting.com/');
    await expect(page.locator('#search-query')).toBeVisible();
  });
});
